def seed_tax_thresholds(apps, schema_editor):
    """يُدخل السقوف المنشورة — idempotent: صفٌّ موجودٌ لا يُعاد كتابته.

    بياناتُ منصّةٍ لا بياناتُ مكتب (بلا `tenant`): السقفُ واحدٌ لكل المكاتب، ومصدرُه
    مكتوبٌ في `source_url` كي يُراجَع عند كل نشرٍ رسميّ جديد.
    """
    TaxThreshold = apps.get_model("accounting_office", "TaxThreshold")
    for row in SEEDED_THRESHOLDS:
        TaxThreshold.objects.get_or_create(
            tax_system=row["tax_system"],
            kind=row["kind"],
            year=row["year"],
            defaults={"amount": row["amount"], "source_url": row["source_url"]},
        )


def unseed_tax_thresholds(apps, schema_editor):
    """عكسٌ يمحو ما زرعته هذه الهجرة وحدها — بمفتاحه الطبيعيّ لا بمبلغه."""
